import './DataTable.css';

export interface Row {
  id: string;
  cells: string[];
}

interface DataTableProps {
  rows: Row[];
  loading: boolean;
}

const PLACEHOLDER_COUNT = 5;
const PLACEHOLDER_CELL_COUNT = 3;

export function DataTable({ rows, loading }: DataTableProps): JSX.Element {
  if (loading) {
    return (
      <table role="table" className="data-table">
        <tbody>
          {Array.from({ length: PLACEHOLDER_COUNT }, (_, i) => (
            <tr key={i} className="data-table-row data-table-row--placeholder">
              {Array.from({ length: PLACEHOLDER_CELL_COUNT }, (_, j) => (
                <td key={j} className="data-table-cell">
                  <span className="data-table-shimmer" />
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    );
  }

  return (
    <table role="table" className="data-table">
      <tbody>
        {rows.map((row) => (
          <tr key={row.id} className="data-table-row">
            {row.cells.map((cell, i) => (
              <td key={i} className="data-table-cell">
                {cell}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

