export function ProductGrid({ products, status }: ProductGridProps): JSX.Element {
  if (status === 'loading') {
    return (
      <ul role="list" className="product-grid">
        {Array.from({ length: GHOST_COUNT }, (_, i) => (
          <li key={i} className="product-grid-item product-grid-item--ghost">
            <div className="product-grid-ghost-name" />
            <div className="product-grid-ghost-price" />
          </li>
        ))}
      </ul>
    );
  }

  return (
    <ul role="list" className="product-grid">
      {products.map((product) => (
        <li key={product.id} className="product-grid-item">
          <span className="product-grid-name">{product.name}</span>
          <span className="product-grid-price">{product.price}</span>
        </li>
      ))}
    </ul>
  );
}

