import './ChipBar.css';

interface ChipBarProps {
  statuses: string[];
  selected: Set<string>;
  onSelectionChange: (selected: Set<string>) => void;
}

export function ChipBar({ statuses, selected, onSelectionChange }: ChipBarProps): JSX.Element {
  function handleClick(status: string): void {
    const next = new Set(selected);
    if (next.has(status)) {
      next.delete(status);
    } else {
      next.add(status);
    }
    onSelectionChange(next);
  }

  return (
    <div className="chip-bar" role="toolbar">
      {statuses.map((status) => (
        <button
          key={status}
          type="button"
          className="chip-bar-chip"
          aria-pressed={selected.has(status)}
          onClick={() => handleClick(status)}
        >
          {status}
        </button>
      ))}
    </div>
  );
}

