import type { Book, BookStatus } from '../../types';
import './BookCard.css';

interface BookCardProps {
  book: Book;
}

const STATUS_LABELS: Record<BookStatus, string> = {
  'want-to-read': 'Want to read',
  reading: 'Reading',
  read: 'Read',
};

const STATUS_CLASS: Record<BookStatus, string> = {
  'want-to-read': '',
  reading: 'book-card-badge--reading',
  read: 'book-card-badge--read',
};

export function BookCard({ book }: BookCardProps): JSX.Element {
  const badgeClass = ['book-card-badge', STATUS_CLASS[book.status]].filter(Boolean).join(' ');

  return (
    <article className="book-card">
      <h3 className="book-card-title">{book.title}</h3>
      <span className="book-card-author">{book.author}</span>
      <span className={badgeClass}>{STATUS_LABELS[book.status]}</span>
    </article>
  );
}
